 const reload=async(id=orgId)=>{
  if(!id)return;
  const results=await Promise.all([
   supabase.from("products").select("*").eq("organization_id",id).order("name"),
   supabase.from("customers").select("*").eq("organization_id",id).order("created_at",{ascending:false}),
   supabase.from("employees").select("*").eq("organization_id",id).order("created_at",{ascending:false}),
   supabase.from("sales").select("*").eq("organization_id",id).order("created_at",{ascending:false}).limit(500),
   supabase.from("sale_items").select("sale_id,quantity,unit_price,unit_cost,line_total").eq("organization_id",id),
   supabase.from("expenses").select("*").eq("organization_id",id).order("expense_date",{ascending:false}).limit(500),
   supabase.from("audit_logs").select("*").eq("organization_id",id).order("created_at",{ascending:false}).limit(100),
   supabase.from("payroll_periods").select("*").eq("organization_id",id).order("period_start",{ascending:false}),
   supabase.from("payroll_items").select("*").eq("organization_id",id),
   supabase.from("shifts").select("*").eq("organization_id",id).order("shift_date",{ascending:false}).limit(300),
   supabase.from("attendance").select("*").eq("organization_id",id).order("work_date",{ascending:false}).limit(300),
   supabase.from("role_permissions").select("role,module,action,allowed").eq("organization_id",id),
   supabase.from("subscription_plans").select("*").eq("is_active",true).order("sort_order"),
   supabase.from("organization_subscriptions").select("*").eq("organization_id",id).maybeSingle()
  ]);
  const failed=results.find(x=>x.error);
  if(failed?.error)throw failed.error;
  const costResult=await supabase.from("product_costs").select("product_id,cost").eq("organization_id",id);
  if(costResult.error)throw costResult.error;
  const costMap=new Map((costResult.data||[]).map((r:any)=>[r.product_id,Number(r.cost)||0]));
  const rawCatalog=((results[0].data||[]) as any[]).map(p=>({...p,cost:costMap.get(p.id)||0})) as Product[];
  const imagePaths=rawCatalog.map(p=>p.image_path).filter((path):path is string=>Boolean(path));
  const signedUrlMap=new Map<string,string>();
  if(imagePaths.length){const {data}=await supabase.storage.from("store-assets").createSignedUrls(imagePaths,3600);for(const item of data||[])if(item.path&&item.signedUrl)signedUrlMap.set(item.path,item.signedUrl);}
  const catalog=rawCatalog.map(p=>({...p,image_url:p.image_path?signedUrlMap.get(p.image_path)||null:null}));
  setProducts(catalog); void saveProductCatalog(id,catalog.map(p=>({...p,cost:0}))).catch(()=>{});
  if(role==="owner"){const {data:pending}=await supabase.rpc("list_pending_store_members");setPendingStaff(pending||[]);}
  if(["owner","admin","hr"].includes(role)){const {data:accounts,error}=await supabase.rpc("list_storeflow_employee_accounts",{p_organization_id:id});if(error)throw error;setEmployeeAccounts(accounts||[]);}
  setCustomers((results[1].data||[]) as Customer[]);
  setEmployees((results[2].data||[]) as Employee[]);
  setSales((results[3].data||[]) as Sale[]);
  setSaleItems((results[4].data||[]) as SaleItem[]);
  setExpenses((results[5].data||[]) as Expense[]);
  setAudit(results[6].data||[]);setPayrollPeriods(results[7].data||[]);setPayrollItems(results[8].data||[]);setShifts(results[9].data||[]);setAttendance(results[10].data||[]);setPermissions(results[11].data||[]);setPlans(results[12].data||[]);setSubscription(results[13].data||null);
  if(role==="employee"){const {data:slips,error:slipError}=await supabase.rpc("get_my_storeflow_pay_slips",{p_organization_id:id});setMyPaySlips(slipError?[]:slips||[]);}
 };
 useEffect(()=>{
  let active=true;
  (async()=>{
   try{
    const {data:{session},error}=await supabase.auth.getSession();
    if(error)throw error;
    if(!session){window.location.replace("/Pos/login/");return;}
    if(!active)return;
    setUserEmail(session.user.email||"");setAccountName(String(session.user.user_metadata?.full_name||""));
    if(!navigator.onLine){const cached=JSON.parse(localStorage.getItem("storeflow:session")||"null");if(cached?.userId===session.user.id&&cached?.orgId){setOrgId(cached.orgId);setOrgName(cached.orgName||"StoreFlow");setRole(cached.role as Role);setOnline(false);setProducts(await readProductCatalog<Product>(cached.orgId));return;}}
    let {data:membership,error:memberError}=await supabase.from("organization_members").select("organization_id,role").eq("user_id",session.user.id).eq("is_active",true).eq("membership_status","active").limit(1).maybeSingle();
    if(memberError)throw memberError;
    if(!membership){
     const {data:state,error:stateError}=await supabase.rpc("get_my_store_membership_state"); if(stateError)throw stateError;
     const current=Array.isArray(state)?state[0]:state;
     if(current?.membership_status==="pending"){setPendingApproval(true);return;}
     if(session.user.user_metadata?.onboarding_role==="owner"){const {error:bootError}=await supabase.rpc("bootstrap_store_owner",{p_org_slug:"storeflow"});if(bootError)throw bootError;const {data:created,error:createdError}=await supabase.from("organization_members").select("organization_id,role").eq("user_id",session.user.id).eq("is_active",true).eq("membership_status","active").limit(1).maybeSingle();if(createdError)throw createdError;membership=created;}
    }
    if(!membership)throw new Error("ไม่พบบัญชีร้านค้าที่ได้รับอนุมัติ กรุณาตรวจสอบรหัสเชิญหรือรอเจ้าของร้านอนุมัติ");
    if(!active)return;
    setOrgId(membership.organization_id);setRole(membership.role as Role);
    const {data:org,error:orgError}=await supabase.from("organizations").select("name").eq("id",membership.organization_id).maybeSingle();
    if(orgError)throw orgError;
    if(org?.name)setOrgName(org.name);if(membership.role==="owner"){const {data:code}=await supabase.rpc("get_store_invite_code");if(code)setInviteCode(String(code));}
    localStorage.setItem("storeflow:session",JSON.stringify({userId:session.user.id,orgId:membership.organization_id,orgName:org?.name||"StoreFlow",role:membership.role}));
    await reload(membership.organization_id);
    if(["owner","admin","hr"].includes(membership.role)){const {data:accounts,error:accountError}=await supabase.rpc("list_storeflow_employee_accounts",{p_organization_id:membership.organization_id});if(accountError)throw accountError;setEmployeeAccounts(accounts||[]);}
    if(membership.role==="owner"){const {data:pending}=await supabase.rpc("list_pending_store_members");setPendingStaff(pending||[]);}
   }catch(e){if(active)setLoadError(e instanceof Error?e.message:"ไม่สามารถโหลดข้อมูลร้านค้าได้");}
   finally{if(active)setLoading(false);}
  })();
  const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>{if(!session)window.location.replace("/Pos/login/");});
  return ()=>{active=false;subscription.unsubscribe();};
 },[supabase]);
 

 useEffect(()=>{
  const url=new URL(window.location.href);const billing=url.searchParams.get("billing");
  if(!billing)return;
  if(billing==="cancel"){url.searchParams.delete("billing");url.searchParams.delete("session_id");window.history.replaceState({},document.title,url.pathname+url.hash);setToast("ยกเลิกการชำระเงินแล้ว คุณสามารถเลือกแพ็กเกจและลองใหม่ได้");return;}
  if(billing!=="success"||!orgId)return;
  const sessionId=url.searchParams.get("session_id");url.searchParams.delete("billing");url.searchParams.delete("session_id");window.history.replaceState({},document.title,url.pathname+url.hash);
  if(!sessionId||!/^cs_(test|live)_[A-Za-z0-9]+$/.test(sessionId)){setToast("ไม่พบรหัส Checkout ที่ถูกต้อง กรุณาตรวจสอบสถานะแพ็กเกจ");return;}
  let cancelled=false;
  (async()=>{for(let attempt=0;attempt<6&&!cancelled;attempt++){
   const {data,error}=await supabase.functions.invoke("storeflow-verify-checkout",{body:{organization_id:orgId,session_id:sessionId}});
   if(!error&&data?.verified){await reload(orgId);if(!cancelled)setToast("ยืนยันการชำระเงินจาก Stripe แล้ว แพ็กเกจได้รับการอัปเดต");return;}
   if(data?.status==="mismatch"){if(!cancelled)setToast("รหัสชำระเงินไม่ตรงกับร้านค้านี้ ระบบไม่ได้เปิดสิทธิ์แพ็กเกจ");return;}
   if(error&&attempt===5){if(!cancelled)setToast("ยังตรวจสอบการชำระเงินไม่ได้ กรุณาตรวจสอบหน้าสมาชิกอีกครั้ง");return;}
   await new Promise(resolve=>window.setTimeout(resolve,1800));
  }if(!cancelled)setToast("Stripe รับรายการแล้ว แต่ Webhook ยังประมวลผลไม่เสร็จ ระบบยังไม่เปิดสิทธิ์จนกว่าจะยืนยันสำเร็จ");})();
  return()=>{cancelled=true;};
 },[orgId,supabase]);

 const syncOfflineOrders=async()=>{if(!orgId||!navigator.onLine)return;const queued=await listOfflineOrders();setOfflineCount(queued.filter(o=>o.organizationId===orgId).length);for(const order of queued){if(order.organizationId!==orgId)continue;const {error}=await supabase.rpc("checkout_sale_idempotent",{p_organization_id:order.organizationId,p_items:order.items,p_payment_method:order.paymentMethod,p_discount:order.discount,p_tax:order.tax,p_customer_id:order.customerId,p_idempotency_key:order.idempotencyKey,p_cash_received:order.cashReceived});if(error)break;await removeOfflineOrder(order.idempotencyKey);}const remaining=await listOfflineOrders();setOfflineCount(remaining.filter(o=>o.organizationId===orgId).length);if(remaining.length<queued.length){await reload();notify("ซิงก์บิลออฟไลน์สำเร็จ");}};
 useEffect(()=>{if(!orgId)return;let mounted=true;const refresh=()=>{if(mounted)void reload(orgId).catch(()=>{});};const channel=supabase.channel("storeflow-live-"+orgId).on("postgres_changes",{event:"*",schema:"public",table:"products",filter:"organization_id=eq."+orgId},refresh).on("postgres_changes",{event:"*",schema:"public",table:"sales",filter:"organization_id=eq."+orgId},refresh).on("postgres_changes",{event:"*",schema:"public",table:"shifts",filter:"organization_id=eq."+orgId},refresh).on("postgres_changes",{event:"*",schema:"public",table:"attendance",filter:"organization_id=eq."+orgId},refresh).on("postgres_changes",{event:"*",schema:"public",table:"payroll_items",filter:"organization_id=eq."+orgId},refresh).subscribe();const network=()=>{setOnline(navigator.onLine);if(navigator.onLine)void syncOfflineOrders();};setOnline(navigator.onLine);void listOfflineOrders().then(q=>{if(mounted)setOfflineCount(q.filter(o=>o.organizationId===orgId).length);});window.addEventListener("online",network);window.addEventListener("offline",network);if(navigator.onLine)void syncOfflineOrders();return()=>{mounted=false;window.removeEventListener("online",network);window.removeEventListener("offline",network);void supabase.removeChannel(channel);};},[orgId]);

 const logout=async()=>{localStorage.removeItem("storeflow:session");await supabase.auth.signOut();window.location.replace("/Pos/login/");};
 const startCheckout=async(planId:string)=>{
  if(planId==="free"){notify("แพ็กเกจ Free ใช้งานได้โดยไม่ต้องชำระเงิน");return;}
  setBusy(true);
  try{const {data,error}=await supabase.functions.invoke("storeflow-create-checkout",{body:{organization_id:orgId,plan_id:planId,billing_interval:planId==="lifetime"?"lifetime":billingInterval}});if(error)throw error;if(!data?.url)throw new Error(data?.error||"ยังไม่สามารถเปิดหน้าชำระเงินได้");window.location.href=data.url;}
  catch(e){notify(e instanceof Error?e.message:"เริ่มชำระเงินไม่สำเร็จ");}finally{setBusy(false);}
 };
 const openBillingPortal=async()=>{
  setBusy(true);
  try{const {data,error}=await supabase.functions.invoke("storeflow-billing-portal",{body:{organization_id:orgId}});if(error)throw error;if(!data?.url)throw new Error(data?.error||"ไม่สามารถเปิดหน้าจัดการสมาชิกได้");window.location.href=data.url;}
  catch(e){notify(e instanceof Error?e.message:"เปิดหน้าจัดการสมาชิกไม่สำเร็จ");}finally{setBusy(false);}
 };
 const createPayroll=async()=>{
  if(!orgId||periodEnd<periodStart){notify("ตรวจสอบช่วงวันที่เงินเดือน");return;}
  if(!employees.some(e=>e.is_active)){notify("ยังไม่มีพนักงานที่เปิดใช้งาน");return;}
  setBusy(true);
  try{
   const {data:periodId,error}=await supabase.rpc("create_storeflow_payroll",{p_organization_id:orgId,p_period_start:periodStart,p_period_end:periodEnd,p_pay_date:payDate});
   if(error)throw error;
   if(!periodId)throw new Error("ฐานข้อมูลไม่ส่งรหัสรอบเงินเดือนกลับมา");
   await reload();setSelectedPeriod(periodId);notify("สร้างรอบเงินเดือนและคำนวณพนักงานเรียบร้อย");
  }catch(e:any){const detail=[e?.message,e?.details,e?.hint,e?.code].filter(Boolean).join(" · ");notify(detail||"สร้างรอบเงินเดือนไม่สำเร็จ");}finally{setBusy(false);}
 };
 const updatePayrollItem=async(item:any,fieldName:string,value:number)=>{
  if(!Number.isFinite(value)||value<0){notify("กรุณากรอกจำนวนเงินตั้งแต่ 0 ขึ้นไป");return;}
  if(!["base_pay","allowances","overtime_pay","commission","bonus","deductions","tax","social_security"].includes(fieldName)){notify("ไม่อนุญาตให้แก้ไขฟิลด์นี้");return;}
  setBusy(true);
  try{const {error}=await supabase.from("payroll_items").update({[fieldName]:value}).eq("id",item.id).eq("organization_id",orgId);if(error)throw error;await reload();notify("อัปเดตรายการเงินเดือนแล้ว");}
  catch(e){notify(e instanceof Error?e.message:"บันทึกรายการเงินเดือนไม่สำเร็จ");}finally{setBusy(false);}
 };
 const updatePayrollStatus=async(period:any,status:"approved"|"paid")=>{
  if(status==="approved"&&period.status!=="draft")return;if(status==="paid"&&period.status!=="approved")return;
  setBusy(true);
  try{
   const patch:any={status};
   if(status==="approved"){patch.approved_by=(await supabase.auth.getUser()).data.user?.id;patch.approved_at=new Date().toISOString();}
   if(status==="paid")patch.pay_date=payDate;
   const {error}=await supabase.from("payroll_periods").update(patch).eq("id",period.id).eq("organization_id",orgId);
   if(error)throw error;
   await reload();notify(status==="approved"?"อนุมัติรอบเงินเดือนแล้ว":"บันทึกสถานะจ่ายเงินเดือนแล้ว");
  }catch(e){notify(e instanceof Error?e.message:"อัปเดตสถานะไม่สำเร็จ");}finally{setBusy(false);}
 };
