 const checkout=async()=>{
  if(!cartItems.length){notify("กรุณาเลือกสินค้าก่อน");return;}if(discountValue>subtotal){notify("ส่วนลดมากกว่ายอดสินค้า");return;}
  setBusy(true);
  if(!navigator.onLine&&payment!=="เงินสด"){notify("ขณะออฟไลน์รับชำระได้เฉพาะเงินสด กรุณาเชื่อมต่ออินเทอร์เน็ตก่อนรับ QR / โอน / บัตร");setBusy(false);return;}
  if(payment==="เงินสด"&&Number(cashReceived)<total){notify("จำนวนเงินที่รับมาต้องไม่น้อยกว่ายอดชำระ");setBusy(false);return;}
  const order={idempotencyKey:crypto.randomUUID(),organizationId:orgId,items:cartItems.map(p=>({product_id:p.id,quantity:p.qty})),paymentMethod:payment,cashReceived:payment==="เงินสด"?Number(cashReceived):null,discount:discountValue,tax:taxValue,customerId:selectedCustomer||null,createdAt:new Date().toISOString()};
  try{
   if(!navigator.onLine){await enqueueOfflineOrder(order);setOfflineCount((await listOfflineOrders()).length);setCart([]);setDiscount("0");setVat(false);setCashReceived("0");setSelectedCustomer("");notify("บันทึกบิลในเครื่องแล้ว รอเชื่อมต่อเพื่อซิงก์");return;}
   const {data:saleId,error}=await supabase.rpc("checkout_sale_idempotent",{p_organization_id:orgId,p_items:order.items,p_payment_method:payment,p_discount:discountValue,p_tax:taxValue,p_customer_id:selectedCustomer||null,p_idempotency_key:order.idempotencyKey,p_cash_received:order.cashReceived});
   if(error)throw error;
   const {data:sale,error:saleError}=await supabase.from("sales").select("*").eq("id",saleId).eq("organization_id",orgId).single();if(saleError)throw saleError;
   await reload();setCart([]);setDiscount("0");setVat(false);setCashReceived("0");setSelectedCustomer("");setRecord(sale);setModal("receipt");notify("บันทึกการขายและตัดสต็อกเรียบร้อย");
  }catch(e){
   if(!navigator.onLine||e instanceof TypeError){await enqueueOfflineOrder(order);setOfflineCount((await listOfflineOrders()).length);setCart([]);setDiscount("0");setVat(false);setCashReceived("0");setSelectedCustomer("");notify("เครือข่ายขัดข้อง บันทึกบิลไว้รอซิงก์แล้ว");}
   else notify(e instanceof Error?e.message:"ทำรายการขายไม่สำเร็จ");
  }finally{setBusy(false);}
 };
 const exportCsv=(name:string,rows:any[])=>{
  if(!rows.length){notify("ไม่มีข้อมูลสำหรับส่งออก");return;}
  const keys=Object.keys(rows[0]);const csv=[keys.join(","),...rows.map(r=>keys.map(k=>'"'+String(r[k]??"").replaceAll('"','""')+'"').join(","))].join("\n");
  const url=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=name+".csv";a.click();URL.revokeObjectURL(url);
 };
 const today=new Date();const todayKey=today.toISOString().slice(0,10);const monthKey=todayKey.slice(0,7);
